async function piAirbnbFillOtp(page, otp) {
  const code = String(otp || '').replace(/\D/g, '');
  if (!code) throw new Error('Empty OTP');
  // Avoid click() — Airbnb overlays often intercept pointer events on #otp-code-input
  const filled = await page.evaluate(function (code) {
    function setNative(el, val) {
      var proto = window.HTMLInputElement && window.HTMLInputElement.prototype;
      var desc = proto && Object.getOwnPropertyDescriptor(proto, 'value');
      if (desc && desc.set) desc.set.call(el, val);
      else el.value = val;
      el.dispatchEvent(new Event('input', { bubbles: true }));
      el.dispatchEvent(new Event('change', { bubbles: true }));
      try {
        el.dispatchEvent(new InputEvent('input', { bubbles: true, data: val, inputType: 'insertText' }));
      } catch (e) {}
    }
    var el = document.querySelector('#otp-code-input') ||
      document.querySelector('input[autocomplete="one-time-code"]') ||
      document.querySelector('input[inputmode="numeric"]');
    if (el) {
      try { el.focus(); } catch (e) {}
      setNative(el, '');
      setNative(el, code);
      return 'single';
    }
    var boxes = Array.prototype.slice.call(document.querySelectorAll('input[maxlength="1"]'));
    if (boxes.length >= Math.min(4, code.length)) {
      for (var i = 0; i < code.length && i < boxes.length; i++) {
        try { boxes[i].focus(); } catch (e) {}
        setNative(boxes[i], code[i]);
      }
      return 'boxes';
    }
    return null;
  }, code);
  if (!filled) {
    const otpInput = page.locator('input[name*="code" i], input[type="tel"]').first();
    if (!(await otpInput.count())) throw new Error('OTP input not found on Airbnb page');
    await otpInput.fill(code, { force: true, timeout: 8000 });
  }
  const cont = page.locator('button:has-text("Continue"), button:has-text("Submit"), button:has-text("Verify"), button[type="submit"]').first();
  if (await cont.count()) await cont.click({ force: true, timeout: 2500 }).catch(function () {});
  await page.waitForTimeout(5000);
}

