async function piAirbnbFillOtp(page, otp) {
  const code = String(otp || '').replace(/\D/g, '');
  if (!code) throw new Error('Empty OTP');
  // Focus without click (overlays intercept pointer), then type digits so Airbnb auto-submits
  await page.evaluate(function () {
    var el = document.querySelector('#otp-code-input') ||
      document.querySelector('input[autocomplete="one-time-code"]') ||
      document.querySelector('input[inputmode="numeric"]');
    if (!el) return;
    try { el.focus(); } catch (e) {}
    try {
      var proto = window.HTMLInputElement && window.HTMLInputElement.prototype;
      var desc = proto && Object.getOwnPropertyDescriptor(proto, 'value');
      if (desc && desc.set) desc.set.call(el, '');
      else el.value = '';
      el.dispatchEvent(new Event('input', { bubbles: true }));
    } catch (e2) {}
  });
  const single = page.locator('#otp-code-input, input[autocomplete="one-time-code"]').first();
  if (await single.count()) {
    await page.keyboard.type(code, { delay: 120 });
  } else {
    const boxes = page.locator('input[maxlength="1"]');
    if ((await boxes.count()) >= Math.min(4, code.length)) {
      for (let i = 0; i < code.length; i++) {
        await boxes.nth(i).focus({ timeout: 2000 }).catch(function () {});
        await page.keyboard.type(code[i], { delay: 80 });
      }
    } else {
      const otpInput = page.locator('input[name*="code" i], input[inputmode="numeric"], input[type="tel"]').first();
      if (!(await otpInput.count())) throw new Error('OTP input not found on Airbnb page');
      await otpInput.focus({ timeout: 3000 }).catch(function () {});
      await page.keyboard.type(code, { delay: 120 });
    }
  }
  // Wait for Airbnb to leave the OTP step (auto-submit) or for password
  try {
    await Promise.race([
      page.waitForSelector('input[type="password"]', { timeout: 12000 }),
      page.waitForFunction(function () {
        return !document.querySelector('#otp-code-input');
      }, { timeout: 12000 }),
      page.waitForURL(/hosting|account/i, { timeout: 12000 })
    ]);
  } catch (e) {}
  await page.waitForTimeout(1500);
}

